STEP A1: HYBRID DISTANCE FUNCTION

Replace field_distance() in the observer WGSL with:

```wgsl
fn field_distance_hybrid(p: vec3f) -> f32 {
    let w = i32(camera_w() + 0.5);
    let field_d = sample_pseudo_sdf_w(p, w);

    var best_exc_d = 999.0;
    for (var i = 0u; i < num_excitations(); i++) {
        let e = excitations[i];
        let exc_w = u32(e.misc.w);
        if (exc_w != u32(w)) { continue; }

        let kind = bitcast<u32>(e.center_kind.w);
        let center = e.center_kind.xyz;
        let dist_to_center = length(p - center);

        // Bounding sphere — skip expensive eval if far away
        var bound = 2.0;
        if (kind == 4u) { bound = e.params.z * 1.5; } // mandelbulb
        else if (kind == 0u) { bound = e.params.x * 1.5; } // sphere
        else if (kind == 3u) { bound = (e.params.x + e.params.y) * 1.5; } // torus
        else { bound = max(e.params.x, max(e.params.y, e.params.z)) * 2.0; } // box/cyl

        if (dist_to_center > bound) {
            best_exc_d = min(best_exc_d, dist_to_center - bound);
            continue;
        }

        let local_p = p - center;
        let rp = quat_inverse_rotate(local_p, e.rotation);

        var d = 999.0;
        switch (kind) {
            case 0u: { d = length(rp) - e.params.x; }
            case 1u: {
                let q = abs(rp) - e.params.xyz;
                d = length(max(q, vec3f(0.0))) + min(max(q.x, max(q.y, q.z)), 0.0);
            }
            case 2u: {
                let dr = sqrt(rp.x*rp.x + rp.z*rp.z) - e.params.x;
                let dv = abs(rp.y) - e.params.y * 0.5;
                d = length(max(vec2f(dr, dv), vec2f(0.0))) + min(max(dr, dv), 0.0);
            }
            case 3u: {
                let qxz = sqrt(rp.x*rp.x + rp.z*rp.z) - e.params.x;
                d = sqrt(qxz*qxz + rp.y*rp.y) - e.params.y;
            }
            case 4u: {
                let scale = e.params.z;
                d = sdf_mandelbulb(rp / scale, e.params.x, i32(e.params.y)) * scale;
            }
            default: {}
        }
        best_exc_d = min(best_exc_d, d);
    }

    return min(field_d, best_exc_d);
}
```

The sdf_mandelbulb function MUST be the full Mandelbulb DE from the 
