```wgsl
fn sdf_mandelbulb(p: vec3f, power: f32, max_iter: i32) -> f32 {
    var z = p;
    var dr = 1.0;
    var r = 0.0;
    for (var i = 0; i < max_iter; i++) {
        r = length(z);
        if (r > 2.0) { break; }
        let theta = acos(z.y / r);
        let phi_a = atan2(z.z, z.x);
        dr = pow(r, power - 1.0) * power * dr + 1.0;
        let zr = pow(r, power);
        let t = theta * power;
        let pa = phi_a * power;
        z = zr * vec3f(sin(t)*cos(pa), cos(t), sin(t)*sin(pa)) + p;
    }
    return 0.5 * log(r) * r / dr;
}
```

Also need sdf_mandelbulb_full that returns iterations and orbit trap 
for the 16-material shader:

```wgsl
struct FractalHit { dist: f32, iterations: i32, last_orbit_r: f32 }

fn sdf_mandelbulb_full(p: vec3f, power: f32, max_iter: i32) -> FractalHit {
    var z = p;
    var dr = 1.0;
    var r = 0.0;
    var last_r = 0.0;
    var iters_used = 0;
    for (var i = 0; i < max_iter; i++) {
        r = length(z);
        if (r > 2.0) { break; }
        last_r = r;
        iters_used = i + 1;
        let theta = acos(z.y / r);
        let phi_a = atan2(z.z, z.x);
        dr = pow(r, power - 1.0) * power * dr + 1.0;
        let zr = pow(r, power);
        let t = theta * power;
        let pa = phi_a * power;
        z = zr * vec3f(sin(t)*cos(pa), cos(t), sin(t)*sin(pa)) + p;
    }
    return FractalHit(0.5 * log(r) * r / dr, iters_used, last_r);
}
