```wgsl
fn cook_torrance_brdf(N: vec3f, L: vec3f, V: vec3f, 
    albedo: vec3f, roughness: f32, metallic: f32) -> vec3f {
    let H = normalize(L + V);
    let NdotL = max(dot(N, L), 0.0);
    let NdotV = max(dot(N, V), 0.001);
    let NdotH = max(dot(N, H), 0.0);
    let VdotH = max(dot(V, H), 0.0);

    let a = roughness * roughness;
    let a2 = a * a;
    let denom_D = NdotH * NdotH * (a2 - 1.0) + 1.0;
    let D = a2 / (3.14159 * denom_D * denom_D);

    let k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
    let G1L = NdotL / (NdotL * (1.0 - k) + k);
    let G1V = NdotV / (NdotV * (1.0 - k) + k);
    let G = G1L * G1V;

    let F0 = mix(vec3f(0.04), albedo, metallic);
    let F = F0 + (1.0 - F0) * pow(1.0 - VdotH, 5.0);

    let spec = D * G * F / (4.0 * NdotL * NdotV + 0.001);
    let diffuse = (1.0 - F) * (1.0 - metallic) * albedo / 3.14159;

    return (diffuse + spec) * NdotL;
}
```

