FEATURE 1: Cook-Torrance BRDF (~20 lines, ~1KB)
═══════════════════════════════════════════════════════════

Add a compact Cook-Torrance:

```wgsl
fn ct_brdf(N: vec3f, L: vec3f, V: vec3f, alb: vec3f, rough: f32, metal: f32) -> vec3f {
    let H = normalize(L + V);
    let NdL = max(dot(N, L), 0.0); let NdV = max(dot(N, V), 0.001);
    let NdH = max(dot(N, H), 0.0); let VdH = max(dot(V, H), 0.0);
    let a = rough * rough; let a2 = a * a;
    let dD = NdH * NdH * (a2 - 1.0) + 1.0;
    let D = a2 / (3.14159 * dD * dD);
    let k = (rough + 1.0) * (rough + 1.0) / 8.0;
    let G = (NdL / (NdL*(1.0-k)+k)) * (NdV / (NdV*(1.0-k)+k));
    let F0 = mix(vec3f(0.04), alb, metal);
    let F = F0 + (1.0 - F0) * pow(1.0 - VdH, 5.0);
    let spec = D * G * F / (4.0 * NdL * NdV + 0.001);
    let diff = (1.0 - F) * (1.0 - metal) * alb / 3.14159;
    return (diff + spec) * NdL;
}
```

