```wgsl
fn field_distance(p: vec3f) -> f32 {
    // ... existing field read ...

    // Analytic grid objects (w=0 only, sharp contacts)
    if (cam_w == 0) {
        // sphere at (-2, 0.5, -2), r=0.4
        field_d = min(field_d, length(p - vec3f(-2.0, 0.5, -2.0)) - 0.4);
        // box at (2, 0.35, -2), half=0.25
        var q = abs(p - vec3f(2.0, 0.35, -2.0)) - vec3f(0.25);
        field_d = min(field_d, length(max(q, vec3f(0.0))) + min(max(q.x,max(q.y,q.z)), 0.0));
        // cylinder at (-2, 0.4, 2), r=0.3, h=0.6
        let cd = vec2f(sqrt(pow(p.x+2.0,2.0)+pow(p.z-2.0,2.0))-0.3, abs(p.y-0.4)-0.3);
        field_d = min(field_d, length(max(cd, vec2f(0.0))) + min(max(cd.x,cd.y), 0.0));
        // torus at (2, 0.4, 2), major=0.5, tube=0.18
        let tq = sqrt(pow(p.x-2.0,2.0)+pow(p.z-2.0,2.0))-0.5;
        field_d = min(field_d, sqrt(tq*tq+pow(p.y-0.4,2.0))-0.18);
        // soft sphere at (0, 0.45, -3), r=0.35
        field_d = min(field_d, length(p - vec3f(0.0, 0.45, -3.0)) - 0.35);
    }
    return field_d;
}
```

