Add sdf_mandelbulb and evaluate ONE Mandelbulb per ray (nearest by 
bounding sphere). This is the most expensive addition — watch FPS.

```wgsl
fn sdf_mb(p: vec3f) -> f32 {
    var z = p; var dr = 1.0; var r = 0.0;
    for (var i = 0; i < 5; i++) {
        r = length(z); if (r > 2.0) { break; }
        let th = acos(z.y/r); let ph = atan2(z.z, z.x);
        dr = pow(r, 7.0) * 8.0 * dr + 1.0;
        let zr = pow(r, 8.0);
        z = zr * vec3f(sin(th*8.0)*cos(ph*8.0), cos(th*8.0), sin(th*8.0)*sin(ph*8.0)) + p;
    }
    return 0.5 * log(r) * r / dr;
}
```

