        case 3: { return vec3f(1.0, 0.0, 0.0); }
        case 4: { return vec3f(0.0, 0.0, 1.0); }
        case 5: { return vec3f(0.0, 1.0, 0.0); }
        case 6: { return vec3f(1.0, 1.0, 0.0); }
        default: { return vec3f(0.5); }
    }
}
fn object_albedo(obj_id: i32) -> vec3f {
    switch (obj_id) {
        case 0: { return vec3f(0.56, 0.57, 0.58); }
        case 1: { return vec3f(0.55, 0.35, 0.18); }
        case 2: { return vec3f(0.83, 0.69, 0.22); }
        case 3: { return vec3f(0.72, 0.45, 0.20); }
        case 4: { return vec3f(0.8, 0.15, 0.1); }
        default: { return vec3f(0.5); }
    }
}

// === Shading ===
fn shade_hit(hp: vec3f, nor: vec3f, rd: vec3f, cam_w: i32, mode: u32) -> vec3f {
    let st = field_surface_type(hp, cam_w);
    var albedo = vec3f(0.3);
    if (st > 0.5 && st < 1.5) { albedo = floor_pattern(hp); }
    else if (st > 1.5 && st < 2.5) { albedo = ceiling_pattern(hp); }
    else if (st > 2.5 && st < 6.5) { albedo = wall_pattern(hp, i32(st + 0.5)); }
    else if (st > 14.5 && st < 15.5) { albedo = vec3f(0.6, 0.75, 0.95); }
    else if (st > 15.5 && st < 16.5) { albedo = vec3f(0.4, 0.05, 0.7); }
    else if (st > 16.5 && st < 17.5) { albedo = vec3f(0.02, 0.02, 0.03); }
    else if (st >= 9.5) { albedo = object_albedo(i32(st - 10.0 + 0.5)); }

    switch (mode) {
        case 1u: { return albedo; }
        case 3u: { return nor * 0.5 + 0.5; }
        case 5u: { return vec3f(0.0); }
        case 8u: {
            let ci = world_to_cell(hp);
            if (ci != 0xFFFFFFFFu) {
                let phi = cell_phi(ci);
                if (phi > 0.55) { return vec3f((phi-0.5)*2.0, 0.0, 0.0); }
                if (phi < 0.45) { return vec3f(0.0, 0.0, (0.5-phi)*2.0); }
                return vec3f(1.0);
            }
            return vec3f(0.0);
        }
        default: {
            let l_dir = normalize(vec3f(0.3, 1.0, 0.2));
            let ndl = max(dot(nor, l_dir), 0.0);
            var light = select(vec3f(0.8, 0.75, 0.9), vec3f(0.7, 0.65, 0.6), cam_w == 0);
            return albedo * (ndl * 0.5 + 0.25) * light;
        }
    }
}

// === Main ===
[redacted:social-handle] [redacted:social-handle](8, 8, 1)
fn main_observe([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let px = gid.x; let py = gid.y;
    if (px >= screen_w() || py >= screen_h()) { return; }
    let w = f32(screen_w()); let h = f32(screen_h());
    let aspect = w / h;
    let half_h = tan(cam_fov() * 0.5); let half_w = half_h * aspect;
    let fwd = normalize(cam_forward());
    let right = normalize(cross(fwd, cam_up()));
    let cup = cross(right, fwd);
    let rd = normalize(fwd + right * ((f32(px)+0.5)/w*2.0-1.0) * half_w + cup * (1.0-(f32(py)+0.5)/h*2.0) * half_h);
    let ro = cam_pos();
    let cs = cell_size_p();
    let cam_w = i32(camera_w() + 0.5);
    var color = vec3f(0.01, 0.01, 0.015);
    var t = 0.0; var prev_d = 1000.0;
    for (var i = 0; i < 128; i++) {
        if (t > 30.0) { break; }
        let p = ro + rd * t;
        let d = field_distance(p);
        if (d < 0.0 && prev_d > 0.0) {
            var lo = t - max(prev_d * 0.9, cs * 0.05); var hi = t;
            for (var b = 0; b < 6; b++) {
                let mid = (lo + hi) * 0.5;
                if (field_distance(ro + rd * mid) < 0.0) { hi = mid; } else { lo = mid; }
            }
            let hp = ro + rd * (lo + hi) * 0.5;
            color = shade_hit(hp, field_normal_w(hp, cam_w), rd, cam_w, render_mode());
            break;
        }
        if (d < cs * 0.005 && d >= 0.0) {
            color = shade_hit(p, field_normal_w(p, cam_w), rd, cam_w, render_mode());
            break;
        }
        prev_d = d;
        t += max(d * 0.9, cs * 0.02);
    }
    var out_color: vec3f;
    if (render_mode() == 0u) { out_color = to_srgb(color); } else { out_color = clamp(color, vec3f(0.0), vec3f(1.0)); }
    textureStore(output, vec2i(i32(px), i32(py)), vec4f(out_color, 1.0));
}

