Add to field_distance: evaluate analytic SDFs for the 5 grid objects 
at w=0 and take min with field pseudo_sdf. This gives sharp object 
edges instead of grid-resolution blobs.

```wgsl
fn eval_obj(p: vec3f, id: i32) -> f32 {
    switch (id) {
        case 0: { return length(p-vec3f(-2,.5,-2))-.4; }
        case 1: { let q=abs(p-vec3f(2,.35,-2))-vec3f(.25);
                   return length(max(q,vec3f(0)))+min(max(q.x,max(q.y,q.z)),0.); }
        case 2: { let d=p-vec3f(-2,.4,2); let r=sqrt(d.x*d.x+d.z*d.z)-.3;
                   let v=abs(d.y)-.3; return length(max(vec2f(r,v),vec2f(0)))+min(max(r,v),0.); }
        case 3: { let d=p-vec3f(2,.4,2); let q=sqrt(d.x*d.x+d.z*d.z)-.5;
                   return sqrt(q*q+d.y*d.y)-.18; }
        case 4: { return length(p-vec3f(0,.45,-3))-.35; }
        default: { return 999.; }
    }
}
```

