Add analytic normals for objects — dispatched when surface_type >= 10:
```wgsl
fn obj_normal(p: vec3f, id: i32) -> vec3f {
    switch (id) {
        case 0: { return normalize(p-vec3f(-2,.5,-2)); }
        case 1: { let q=p-vec3f(2,.35,-2); let a=abs(q);
                   if(a.x>=a.y&&a.x>=a.z){return vec3f(sign(q.x),0,0);}
                   if(a.y>=a.x&&a.y>=a.z){return vec3f(0,sign(q.y),0);}
                   return vec3f(0,0,sign(q.z)); }
        case 2: { let d=p-vec3f(-2,.4,2); let r=sqrt(d.x*d.x+d.z*d.z);
                   let dr=r-.3; let dv=abs(d.y)-.3;
                   if(dr>dv){if(r>.001){return normalize(vec3f(d.x,0,d.z));}return vec3f(1,0,0);}
                   return vec3f(0,sign(d.y),0); }
        case 3: { let d=p-vec3f(2,.4,2); let r=sqrt(d.x*d.x+d.z*d.z);
                   var rd=vec2f(d.x,d.z); if(r>.001){rd/=r;}
                   let rp=vec3f(rd.x*.5,0,rd.y*.5);
                   return normalize(d-rp); }
        case 4: { return normalize(p-vec3f(0,.45,-3)); }
        default: { return vec3f(0,1,0); }
    }
}
```

