Add compact Cook-Torrance:
```wgsl
fn ct_brdf(N: vec3f, L: vec3f, V: vec3f, alb: vec3f, rough: f32, metal: f32) -> vec3f {
    let H=normalize(L+V); let NdL=max(dot(N,L),0.); let NdV=max(dot(N,V),.001);
    let NdH=max(dot(N,H),0.); let VdH=max(dot(V,H),0.);
    let a=rough*rough; let a2=a*a;
    let dD=NdH*NdH*(a2-1.)+1.; let D=a2/(3.14159*dD*dD);
    let k=(rough+1.)*(rough+1.)/8.; let G=NdL/(NdL*(1.-k)+k)*NdV/(NdV*(1.-k)+k);
    let F0=mix(vec3f(.04),alb,metal); let F=F0+(1.-F0)*pow(1.-VdH,5.);
    let spec=D*G*F/(4.*NdL*NdV+.001);
    let diff=(1.-F)*(1.-metal)*alb/3.14159;
    return (diff+spec)*NdL;
}
```

