Add the compact Mandelbulb distance estimator:
```wgsl
fn sdf_mb(p: vec3f, pw: f32, mi: i32) -> f32 {
    var z=p; var dr=1.; var r=0.;
    for(var i=0;i<mi;i++){
        r=length(z); if(r>2.){break;}
        let th=acos(z.y/r); let ph=atan2(z.z,z.x);
        dr=pow(r,pw-1.)*pw*dr+1.;
        let zr=pow(r,pw); let t=th*pw; let pa=ph*pw;
        z=zr*vec3f(sin(t)*cos(pa),cos(t),sin(t)*sin(pa))+p;
    }
    return .5*log(r)*r/dr;
}
```

Add the 4 Mandelbulb positions and evaluation in field_distance. Use 
the bounding sphere optimization — only evaluate the closest Mandelbulb 
per ray step:

```wgsl
const MB_SCALE: f32 = 0.45;
fn mb_center(row: i32, col: i32) -> vec3f {
    return vec3f(-2.5 + f32(col) * 5.0, 1.8, -2.5 + f32(row) * 5.0);
}

// In field_distance, after grid object loop:
if (cam_w_int == 0) {
    for (var bi = 0; bi < 4; bi++) {
        let r = bi / 2; let c = bi % 2;
        let ctr = mb_center(r, c);
        let dist = length(p - ctr);
        if (dist < MB_SCALE * 2.0) {
            let local = (p - ctr) / MB_SCALE;
            let md = sdf_mb(local, 8.0, 5) * MB_SCALE;
            field_d = min(field_d, md);
        } else {
            field_d = min(field_d, dist - MB_SCALE * 1.2);
        }
    }
}
```

Add Mandelbulb normals via finite difference:
```wgsl
fn mb_normal(p: vec3f, ctr: vec3f) -> vec3f {
    let s = MB_SCALE; let e = s * 0.001;
    let lp = (p - ctr) / s;
    return normalize(vec3f(
        sdf_mb(lp+vec3f(e,0,0),8.,5)-sdf_mb(lp-vec3f(e,0,0),8.,5),
        sdf_mb(lp+vec3f(0,e,0),8.,5)-sdf_mb(lp-vec3f(0,e,0),8.,5),
        sdf_mb(lp+vec3f(0,0,e),8.,5)-sdf_mb(lp-vec3f(0,0,e),8.,5)));
}
```

