Add compact reflection tracing using field_distance (which now 
includes analytic objects + Mandelbulbs):

```wgsl
fn trace_refl(origin: vec3f, dir: vec3f) -> vec3f {
    let cs = cell_size_p();
    var t = 0.0;
    for (var i = 0; i < 30; i++) {
        let p = origin + dir * t;
        let d = field_distance(p);
        if (d < cs * 0.01) {
            let w = i32(camera_w() + 0.5);
            let st = field_surface_type(p, w);
            if (st >= 9.5) { return object_albedo(i32(st-10.+.5)); }
            if (st > 0.5 && st < 1.5) { return floor_pattern(p); }
            if (st > 1.5 && st < 2.5) { return ceiling_pattern(p); }
            if (st > 2.5 && st < 6.5) { return wall_pattern(p, i32(st+.5)); }
            return vec3f(0.3);
        }
        if (t > 20.) { break; }
        t += max(d * 0.9, cs * 0.1);
    }
    return vec3f(0.01, 0.01, 0.015);
}
```

