```wgsl
fn wall_pattern(hp: vec3f, wall_id: i32) -> vec3f {
    switch (wall_id) {
        case 3: { // north: red + horizontal stripes
            let stripe = i32(floor(hp.y * 8.0));
            if (stripe % 2 == 0) { return vec3f(1,0,0); }
            return vec3f(0.15,0,0);
        }
        case 4: { // south: blue + vertical stripes
            let stripe = i32(floor(hp.x * 6.0 + 5.0));
            if (stripe % 2 == 0) { return vec3f(0,0,1); }
            return vec3f(0,0,0.15);
        }
        case 5: { // east: green + checkerboard
            let tx = i32(floor(hp.y * 6.0));
            let tz = i32(floor(hp.z * 6.0 + 5.0));
            if ((tx+tz)%2==0) { return vec3f(0,1,0); }
            return vec3f(0,0.15,0);
        }
        case 6: { // west: yellow + grid
            let gx = i32(floor(hp.y * 5.0));
            let gz = i32(floor(hp.z * 5.0 + 5.0));
            let on_line = (abs(fract(hp.y*5.)-.5) > .35) || (abs(fract(hp.z*5.+5.)-.5) > .35);
            if (on_line) { return vec3f(.15,.12,0); }
            return vec3f(1,1,0);
        }
        default: { return vec3f(0.5); }
    }
}
```

