```rust
fn read_cell_from_gpu(physics: &GpuPhysics, device: &wgpu::Device, 
                      queue: &wgpu::Queue, cell_id: u32) -> [f32; 48] {
    let byte_offset = cell_id as u64 * 192;
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("cell_readback"),
        size: 192,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut encoder = device.create_command_encoder(&Default::default());
    encoder.copy_buffer_to_buffer(
        physics.current_buffer(), byte_offset, &staging, 0, 192);
    queue.submit(std::iter::once(encoder.finish()));

    let slice = staging.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| tx.send(r).unwrap());
    device.poll(wgpu::Maintain::Wait);
    rx.recv().unwrap().unwrap();

    let data = slice.get_mapped_range();
    let floats: &[f32] = bytemuck::cast_slice(&data);
    let mut result = [0.0f32; 48];
    result.copy_from_slice(&floats[..48]);
    result
}
```

