/// GPU-side entity representation.
/// MUST match GpuExcitation layout exactly (80 bytes) for backward 
/// compatibility with the observer shader.
#[repr(C)]
#[derive(Clone, Copy, Pod, Zeroable)]
pub struct GpuEntity {
    pub center: [f32; 3],       // world position
    pub kind: u32,              // 0=sphere, 1=box, 2=cylinder, 3=torus, 4=mandelbulb, 5=capsule
    pub params: [f32; 4],       // shape params (radius, half-extents, power/iters/scale, etc.)
    pub material: [f32; 4],     // material[0]=surface_type, [1]=mat_idx, [2..3]=reserved
    pub rotation: [f32; 4],     // quaternion (x,y,z,w) — identity=(0,0,0,1)
    pub misc: [f32; 4],         // [0..2]=velocity, [3]=w_layer
}

/// CPU-side entity with physics state
pub struct Entity {
    pub gpu: GpuEntity,
    // Physics state (not uploaded to GPU)
    pub prev_position: [f32; 3],    // for Verlet integration
    pub angular_velocity: f32,       // rad/s around local Y
    pub squish: f32,                 // soft body deformation 0..1
    pub squish_velocity: f32,        // soft body spring velocity
    pub strand_data: Option<StrandBundle>, // hair strands if any
}

/// Hair strand bundle attached to an entity
pub struct StrandBundle {
    pub strands: Vec<HairStrand>,
}

/// Single hair strand — 4 control points, Verlet physics
pub struct HairStrand {
    pub points: [[f32; 3]; 4],      // p0=root (fixed), p1, p2, p3=tip
    pub prev_points: [[f32; 3]; 4], // previous positions for Verlet
    pub radius: [f32; 4],           // taper: root thick, tip thin
    pub color: [f32; 3],
    pub segment_length: f32,
}

impl Entity {
    pub fn new(gpu: GpuEntity) -> Self {
        Self {
            prev_position: gpu.center,
            angular_velocity: 0.0,
            squish: 0.0,
            squish_velocity: 0.0,
            strand_data: None,
            gpu,
        }
    }
}
