use crate::entity::*;

pub struct EntityRegistry {
    pub entities: Vec<Entity>,
    pub gpu_buffer: Vec<GpuEntity>, // staging for GPU upload
    pub dirty: bool,
}

impl EntityRegistry {
    pub fn new() -> Self {
        Self { entities: Vec::new(), gpu_buffer: Vec::new(), dirty: true }
    }

    pub fn add(&mut self, entity: Entity) -> usize {
        let id = self.entities.len();
        self.entities.push(entity);
        self.dirty = true;
        id
    }

    pub fn get(&self, id: usize) -> &Entity { &self.entities[id] }
    pub fn get_mut(&mut self, id: usize) -> &mut Entity { 
        self.dirty = true;
        &mut self.entities[id] 
    }

    /// Prepare GPU buffer from entity state
    pub fn build_gpu_buffer(&mut self) -> &[GpuEntity] {
        self.gpu_buffer.clear();
        for e in &self.entities {
            self.gpu_buffer.push(e.gpu);
        }
        self.dirty = false;
        &self.gpu_buffer
    }

    pub fn len(&self) -> usize { self.entities.len() }
}
