fn update_entity_physics(registry: &mut EntityRegistry, dt: f32, elapsed: f32) {
    for entity in registry.entities.iter_mut() {
        // Rotation
        if entity.angular_velocity.abs() > 0.001 {
            let angle = elapsed * entity.angular_velocity;
            let half = angle * 0.5;
            entity.gpu.rotation = [0.0, half.sin(), 0.0, half.cos()];
        }

        // Soft body spring
        if entity.squish.abs() > 0.001 || entity.squish_velocity.abs() > 0.001 {
            let k = 25.0;   // spring stiffness
            let b = 4.0;    // damping
            let rest = 0.15; // resting squish when on floor
            let accel = -k * (entity.squish - rest) - b * entity.squish_velocity;
            entity.squish_velocity += accel * dt;
            entity.squish += entity.squish_velocity * dt;
            entity.squish = entity.squish.clamp(0.0, 0.9);
            // Store squish in misc[0] for GPU to read (if shader supports it)
            entity.gpu.misc[0] = entity.squish;
        }
    }
    registry.dirty = true;
}
```

