Add Verlet update for hair strands:
```rust
fn update_hair_strands(entity: &mut Entity, dt: f32, elapsed: f32) {
    if let Some(ref mut bundle) = entity.strand_data {
        let gravity = [0.0f32, -9.81, 0.0];
        for strand in bundle.strands.iter_mut() {
            let wind = [
                (elapsed * 2.0 + strand.points[0][0] * 5.0).sin() * 0.5,
                0.0,
                (elapsed * 1.7 + strand.points[0][2] * 3.0).cos() * 0.3,
            ];

            // Verlet for points 1, 2, 3 (point 0 is fixed root)
            for i in 1..4 {
                let mut vel = [0.0f32; 3];
                for d in 0..3 {
                    vel[d] = (strand.points[i][d] - strand.prev_points[i][d]) * 0.97;
                }
                let prev = strand.points[i];
                for d in 0..3 {
                    strand.points[i][d] += vel[d] + (gravity[d] + wind[d]) * dt * dt;
                }
                strand.prev_points[i] = prev;

                // Distance constraint: maintain segment length
                let parent = strand.points[i - 1];
                let mut dir = [0.0f32; 3];
                let mut len = 0.0f32;
                for d in 0..3 {
                    dir[d] = strand.points[i][d] - parent[d];
                    len += dir[d] * dir[d];
                }
                len = len.sqrt().max(0.001);
                for d in 0..3 {
                    strand.points[i][d] = parent[d] + dir[d] / len * strand.segment_length;
                }
            }
        }
    }
}
```

