use std::io::Write;
use std::fs::OpenOptions;
use std::time::Instant;

pub struct TelemetryLog {
    [redacted:file-uri] std::fs::File,
    start: Instant,
    frame_count: u64,
}

impl TelemetryLog {
    pub fn new() -> Self {
        let file = OpenOptions::new()
            .create(true).write(true).truncate(true)
            .open("logs/telemetry.log")
            .expect("Failed to create telemetry log");
        let mut log = Self { file, start: Instant::now(), frame_count: 0 };
        writeln!(log.file, "# LoA Telemetry Log").ok();
        writeln!(log.file, "# Started: {:?}", std::time::SystemTime::now()).ok();
        writeln!(log.file, "# Format: timestamp_ms,frame,event,data").ok();
        log
    }

    fn ts(&self) -> u64 {
        self.start.elapsed().as_millis() as u64
    }

    pub fn log_frame_start(&mut self) {
        self.frame_count += 1;
    }

    pub fn log_pass(&mut self, name: &str, duration_us: u64) {
        if self.frame_count % 60 == 0 { // log every 60th frame
            writeln!(self.file, "{},{},pass,{}={}", 
                self.ts(), self.frame_count, name, duration_us).ok();
        }
    }

    pub fn log_fps(&mut self, fps: f32, frame_time_ms: f32) {
        if self.frame_count % 60 == 0 {
            writeln!(self.file, "{},{},fps,{:.1},{:.2}", 
                self.ts(), self.frame_count, fps, frame_time_ms).ok();
        }
    }

    pub fn log_event(&mut self, event: &str) {
        writeln!(self.file, "{},{},event,{}", 
            self.ts(), self.frame_count, event).ok();
    }

    pub fn log_gpu_memory(&mut self, label: &str, bytes: u64) {
        writeln!(self.file, "{},{},gpu_mem,{}={}", 
            self.ts(), self.frame_count, label, bytes).ok();
    }

    pub fn flush(&mut self) {
        self.file.flush().ok();
    }
}
