fn wall_pattern(hp: vec3f, wall_id: i32) -> vec3f {
    switch (wall_id) {
        case 3: { // NORTH: red with horizontal stripes + "N" letter
            let sy = fract(hp.y * 8.0);
            var base = vec3f(1.0, 0.0, 0.0);
            if (sy < 0.15 || sy > 0.85) { base *= 0.15; }
            // "N" letter centered on wall
            let lx = (hp.x + 5.0) / 10.0; // 0..1 across wall
            let ly = (hp.y - 0.5) / 2.5;  // 0..1 vertically
            if (lx > 0.42 && lx < 0.58 && ly > 0.2 && ly < 0.8) {
                let nx = (lx - 0.42) / 0.16;
                let ny = (ly - 0.2) / 0.6;
                // N shape: left bar, right bar, diagonal
                if (nx < 0.2 || nx > 0.8 || abs(ny - nx) < 0.15) {
                    base = vec3f(0.02);
                }
            }
            return base;
        }
        case 4: { // SOUTH: blue with vertical stripes
            let sx = fract((hp.x + 5.0) * 3.0);
            if (sx < 0.1 || sx > 0.9) { return vec3f(0.0, 0.0, 0.12); }
            return vec3f(0.0, 0.0, 1.0);
        }
        case 5: { // EAST: green + black checkerboard
            let tx = i32(floor(hp.y * 6.0));
            let tz = i32(floor((hp.z + 5.0) * 6.0));
            if ((tx + tz) % 2 == 0) { return vec3f(0.0, 0.9, 0.0); }
            return vec3f(0.02);
        }
        case 6: { // WEST: yellow grid squares
            let gy = fract(hp.y * 5.0);
            let gz = fract((hp.z + 5.0) * 5.0);
            let on_line = gy < 0.06 || gy > 0.94 || gz < 0.06 || gz > 0.94;
            if (on_line) { return vec3f(0.12, 0.10, 0.0); }
            return vec3f(1.0, 1.0, 0.0);
        }
        default: { return vec3f(0.5); }
    }
}
