    let tx = i32(floor(hp.x + 5.0));
    let tz = i32(floor(hp.z + 5.0));
    var col = select(vec3f(0.9), vec3f(0.08), (tx + tz) % 2 != 0);

    // North arrow (red, -Z direction)
    if (abs(hp.x) < 0.12 && hp.z > -3.5 && hp.z < -0.5) { col = vec3f(0.9, 0.0, 0.0); }
    // Arrowhead
    if (hp.z < -3.0 && hp.z > -3.8 && abs(hp.x) < (-hp.z - 3.0) * 0.6) { col = vec3f(0.9,0,0); }

    // East arrow (green, +X direction)
    if (abs(hp.z) < 0.12 && hp.x > 0.5 && hp.x < 3.5) { col = vec3f(0.0, 0.8, 0.0); }
    if (hp.x > 3.0 && hp.x < 3.8 && abs(hp.z) < (hp.x - 3.0) * 0.6) { col = vec3f(0,0.8,0); }

    // Center cross
    if (abs(hp.x) < 0.05 && abs(hp.z) < 0.3) { col = vec3f(1.0); }
    if (abs(hp.z) < 0.05 && abs(hp.x) < 0.3) { col = vec3f(1.0); }

    // Distance rings at 1m, 2m, 3m, 4m from center
    let dist = sqrt(hp.x*hp.x + hp.z*hp.z);
    for (var r = 1; r <= 4; r++) {
        if (abs(dist - f32(r)) < 0.03) { col = vec3f(0.4, 0.4, 0.5); }
    }

    return col;
}
