```rust
use std::io::Write;
use std::fs::{self, OpenOptions};
use std::time::{Instant, SystemTime};

pub struct Logger {
    session_file: std::fs::File,
    csv_file: std::fs::File,
    start: Instant,
    frame_count: u64,
    last_fps_log: Instant,
    // Accumulators for per-pass timing (reset every log interval)
    pass_times: std::collections::HashMap<String, (f64, u64)>, // (total_us, count)
}

impl Logger {
    pub fn new() -> Self {
        fs::create_dir_all("logs").ok();
        let now = chrono_lite_timestamp(); // "20260411_143052"

        let session_path = format!("logs/session_{}.log", now);
        let mut session_file = OpenOptions::new()
            .create(true).write(true).truncate(true)
            .open(&session_path).expect("Failed to create session log");

        let csv_path = "logs/telemetry.csv";
        let csv_exists = std::path::Path::new(csv_path).exists();
        let mut csv_file = OpenOptions::new()
            .create(true).append(true)
            .open(csv_path).expect("Failed to create telemetry CSV");

        if !csv_exists {
            writeln!(csv_file, "timestamp_ms,frame,category,key,value").ok();
        }

        writeln!(session_file, "═══════════════════════════════════════════").ok();
        writeln!(session_file, "  LABYRINTH OF APOCALYPSE — SESSION LOG").ok();
        writeln!(session_file, "  Started: {:?}", SystemTime::now()).ok();
        writeln!(session_file, "═══════════════════════════════════════════").ok();
        writeln!(session_file, "").ok();

        eprintln!("Logging to: {} + {}", session_path, csv_path);

        Self {
            session_file, csv_file,
            start: Instant::now(),
            frame_count: 0,
            last_fps_log: Instant::now(),
            pass_times: std::collections::HashMap::new(),
        }
    }

    fn ts(&self) -> u64 { self.start.elapsed().as_millis() as u64 }

    // ─── STARTUP INFO ───────────────────────────────────

    pub fn log_startup(&mut self, info: &StartupInfo) {
        let msg = format!(
            "Grid: {}×{}×{}×{} (cs={:.3}m, cells={})\n\
             Entities: {} base\n\
             GPU: {} adapter\n\
             Resolution: {}×{}\n\
             Observer WGSL: {} bytes ({} KB)\n\
             Physics passes: {}\n\
             Render passes: {}",
            info.grid_nx, info.grid_ny, info.grid_nz, info.grid_nw,
            info.cell_size, info.total_cells,
            info.num_entities,
            info.adapter_name,
            info.render_w, info.render_h,
            info.wgsl_size, info.wgsl_size / 1024,
            info.physics_passes, info.render_passes);
        self.session(&msg);

        self.csv("startup", "grid_cells", info.total_cells as f64);
        self.csv("startup", "entities", info.num_entities as f64);
        self.csv("startup", "wgsl_bytes", info.wgsl_size as f64);
        self.csv("startup", "render_w", info.render_w as f64);
        self.csv("startup", "render_h", info.render_h as f64);
    }

    pub fn log_gpu_memory(&mut self, label: &str, bytes: u64) {
        self.session(&format!("GPU buffer: {} = {} bytes ({:.1} MB)", 
            label, bytes, bytes as f64 / 1048576.0));
        self.csv("gpu_mem", label, bytes as f64);
    }

    // ─── PER-FRAME ──────────────────────────────────────

    pub fn frame_start(&mut self) {
        self.frame_count += 1;
    }

    pub fn log_pass_time(&mut self, name: &str, duration_us: u64) {
        let entry = self.pass_times.entry(name.to_string())
            .or_insert((0.0, 0));
        entry.0 += duration_us as f64;
        entry.1 += 1;
    }

    pub fn log_fps(&mut self, fps: f32, frame_time_ms: f32) {
        // Log to CSV every 5 seconds
        if self.last_fps_log.elapsed().as_secs_f32() > 5.0 {
            self.last_fps_log = Instant::now();
            self.csv("perf", "fps", fps as f64);
            self.csv("perf", "frame_ms", frame_time_ms as f64);

            // Dump pass averages
            for (name, (total, count)) in &self.pass_times {
                if *count > 0 {
                    let avg = total / *count as f64;
                    self.csv("pass_avg_us", name, avg);
                }
            }
            self.pass_times.clear();

            // Session log summary
            self.session(&format!("Frame {} | {:.0} FPS | {:.2}ms", 
                self.frame_count, fps, frame_time_ms));

            self.flush();
        }
    }

    // ─── EVENTS ─────────────────────────────────────────

    pub fn log_event(&mut self, event: &str) {
        self.session(&format!("EVENT: {}", event));
        self.csv("event", event, 0.0);
    }

    pub fn log_screenshot(&mut self, path: &str, width: u32, height: u32) {
        self.session(&format!("Screenshot: {} ({}×{})", path, width, height));
        self.csv("event", "screenshot", self.frame_count as f64);
    }

    pub fn log_mode_change(&mut self, mode: &str) {
        self.session(&format!("Render mode → {}", mode));
        self.csv("event", &format!("mode_{}", mode), self.frame_count as f64);
    }

    pub fn log_camera(&mut self, pos: [f32; 3], yaw: f32, pitch: f32) {
        self.csv("camera", "x", pos[0] as f64);
        self.csv("camera", "y", pos[1] as f64);
        self.csv("camera", "z", pos[2] as f64);
    }

    pub fn log_w_layer_change(&mut self, w: f32, aperture: f32) {
        self.session(&format!("W-layer → w={:.0} aperture={:.1}", w, aperture));
        self.csv("event", "w_layer", w as f64);
    }

    pub fn log_entity_physics(&mut self, entity_count: usize, 
        hair_segments: usize, physics_time_us: u64) {
        if self.frame_count % 300 == 0 {
            self.csv("entity", "count", entity_count as f64);
            self.csv("entity", "hair_segs", hair_segments as f64);
            self.csv("entity", "physics_us", physics_time_us as f64);
        }
    }

    pub fn log_mcp_request(&mut self, method: &str, duration_us: u64) {
        self.session(&format!("MCP: {} ({} μs)", method, duration_us));
        self.csv("mcp", method, duration_us as f64);
    }

    pub fn log_error(&mut self, error: &str) {
        self.session(&format!("ERROR: {}", error));
        self.csv("error", error, 0.0);
        self.flush();
    }

    pub fn log_warning(&mut self, warning: &str) {
        self.session(&format!("WARN: {}", warning));
    }

    // ─── INTERNALS ──────────────────────────────────────

    fn session(&mut self, msg: &str) {
        let ts = self.ts();
        let secs = ts / 1000;
        let ms = ts % 1000;
        writeln!(self.session_file, "[{:4}.{:03}] {}", secs, ms, msg).ok();
    }

    fn csv(&mut self, category: &str, key: &str, value: f64) {
        writeln!(self.csv_file, "{},{},{},{},{}", 
            self.ts(), self.frame_count, category, key, value).ok();
    }

    pub fn flush(&mut self) {
        self.session_file.flush().ok();
        self.csv_file.flush().ok();
    }
}

