```wgsl
fn shadow_test(origin: vec3f, light_dir: vec3f) -> f32 {
    var t = cell_size_p() * 3.0;
    for (var i = 0; i < 20; i++) {
        let p = origin + light_dir * t;
        let d = field_distance(p); // field only, skip analytic for speed
        if (d < cell_size_p() * 0.01) { return 0.15; } // in shadow
        if (t > 8.0) { break; }
        t += max(d * 0.8, cell_size_p() * 0.5);
    }
    return 1.0; // fully lit
}
```

