```wgsl
fn in_letter(font: array<u32, 7>, u: f32, v: f32) -> bool {
    let col = i32(u * 5.0);
    let row = i32(v * 7.0);
    if (col < 0 || col >= 5 || row < 0 || row >= 7) { return false; }
    return ((font[6 - row] >> u32(4 - col)) & 1u) != 0u;
}

// "L" "o" "A" at different sizes on north wall
fn text_on_wall(hp: vec3f) -> vec3f {
    // Scale 1: Large (1m tall) at center of wall
    let lx = (hp.x + 1.5) / 3.0; // 3m wide region
    let ly = (hp.y - 0.5) / 1.0;  // 1m tall
    if (lx >= 0.0 && lx < 1.0 && ly >= 0.0 && ly < 1.0) {
        // "L"
        let cx = lx * 3.0; // 3 chars wide
        let char_x = fract(cx);
        let char_idx = i32(cx);
        let L: array<u32, 7> = array(16u,16u,16u,16u,16u,16u,31u);
        let O: array<u32, 7> = array(14u,17u,17u,17u,17u,17u,14u);
        let A: array<u32, 7> = array(14u,17u,17u,31u,17u,17u,17u);
        var hit = false;
        if (char_idx == 0) { hit = in_letter(L, char_x, ly); }
        else if (char_idx == 1) { hit = in_letter(O, char_x, ly); }
        else if (char_idx == 2) { hit = in_letter(A, char_x, ly); }
        if (hit) { return vec3f(0.02); } // dark text
    }

    // Scale 2: Medium (0.3m tall) below the large text
    let mx = (hp.x + 1.0) / 2.0;
    let my = (hp.y - 0.1) / 0.3;
    if (mx >= 0.0 && mx < 1.0 && my >= 0.0 && my < 1.0) {
        let cx = mx * 3.0;
        let char_x = fract(cx);
        let char_idx = i32(cx);
        let L: array<u32, 7> = array(16u,16u,16u,16u,16u,16u,31u);
        let O: array<u32, 7> = array(14u,17u,17u,17u,17u,17u,14u);
        let A: array<u32, 7> = array(14u,17u,17u,31u,17u,17u,17u);
        var hit = false;
        if (char_idx == 0) { hit = in_letter(L, char_x, my); }
        else if (char_idx == 1) { hit = in_letter(O, char_x, my); }
        else if (char_idx == 2) { hit = in_letter(A, char_x, my); }
        if (hit) { return vec3f(0.02); }
    }

    // Scale 3: Tiny (0.1m tall) — tests minimum readable size
    let sx = (hp.x - 1.0) / 1.5;
    let sy2 = (hp.y - 0.1) / 0.1;
    if (sx >= 0.0 && sx < 1.0 && sy2 >= 0.0 && sy2 < 1.0) {
        let cx = sx * 3.0;
        let char_x = fract(cx);
        let char_idx = i32(cx);
        let L: array<u32, 7> = array(16u,16u,16u,16u,16u,16u,31u);
        let O: array<u32, 7> = array(14u,17u,17u,17u,17u,17u,14u);
        let A: array<u32, 7> = array(14u,17u,17u,31u,17u,17u,17u);
        var hit = false;
        if (char_idx == 0) { hit = in_letter(L, char_x, sy2); }
        else if (char_idx == 1) { hit = in_letter(O, char_x, sy2); }
        else if (char_idx == 2) { hit = in_letter(A, char_x, sy2); }
        if (hit) { return vec3f(0.02); }
    }

    return vec3f(-1.0); // no text hit, use normal wall pattern
}
