B1: BITMAP FONT SYSTEM (~15 lines, shared by all text)

```wgsl
fn glyph(ch: i32, row: i32) -> u32 {
    // 5x7 bitmap font — each row is 5 bits, 7 rows per glyph
    // Glyphs: L=0, o=1, A=2, 1=3, 2=4, 3=5, 4=6, S=7, D=8, F=9
    let fonts = array<array<u32,7>,10>(
        array(16u,16u,16u,16u,16u,16u,31u),     // L
        array(14u,17u,17u,17u,17u,17u,14u),      // o
        array(14u,17u,17u,31u,17u,17u,17u),      // A
        array(4u,12u,4u,4u,4u,4u,14u),           // 1
        array(14u,17u,1u,6u,8u,16u,31u),         // 2
        array(14u,17u,1u,6u,1u,17u,14u),         // 3
        array(2u,6u,10u,18u,31u,2u,2u),          // 4
        array(14u,17u,16u,14u,1u,17u,14u),       // S
        array(28u,18u,17u,17u,17u,18u,28u),      // D
        array(31u,16u,16u,30u,16u,16u,16u)       // F
    );
    if (ch < 0 || ch > 9 || row < 0 || row > 6) { return 0u; }
    return fonts[ch][row];
}

fn in_char(ch: i32, u: f32, v: f32) -> bool {
    let col = i32(u * 5.0);
    let row = i32(v * 7.0);
    if (col<0||col>=5||row<0||row>=7) { return false; }
    return ((glyph(ch, 6-row) >> u32(4-col)) & 1u) != 0u;
}

fn render_text(text: array<i32,4>, num_chars: i32, 
               u: f32, v: f32) -> bool {
    let ci = i32(u * f32(num_chars));
    if (ci < 0 || ci >= num_chars) { return false; }
    let cu = fract(u * f32(num_chars));
    return in_char(text[ci], cu, v);
}
```

B2: NORTH WALL — OPTOMETRIST TEXT CHART

"LoA" at 8 decreasing sizes. Each row is a different scale. Dark text 
on red background.

```wgsl
fn north_wall(hp: vec3f) -> vec3f {
    let base = vec3f(0.9, 0.0, 0.0); // red
    let text_col = vec3f(0.02);
    let loa = array<i32,4>(0, 1, 2, -1); // L, o, A
    let nums = array<i32,4>(3, 4, 5, 6); // 1, 2, 3, 4

    // 8 rows at exponentially decreasing sizes
    let sizes = array<f32,8>(2.0, 1.0, 0.5, 0.25, 0.125, 0.06, 0.03, 0.06);
    let y_starts = array<f32,8>(1.8, 1.4, 1.1, 0.9, 0.75, 0.65, 0.58, 0.48);

    for (var row = 0; row < 8; row++) {
        let h = sizes[row];
        let w = h * 3.0 * 5.0 / 7.0; // aspect corrected width for 3 chars
        let y0 = y_starts[row];
        let x0 = -w * 0.5; // centered
        let u = (hp.x - x0) / w;
        let v = (hp.y - y0) / h;
        if (u >= 0.0 && u < 1.0 && v >= 0.0 && v < 1.0) {
            var chars = loa;
            if (row == 7) { chars = nums; }
            let nc = select(3, 4, row == 7);
            if (render_text(chars, nc, u, v)) { return text_col; }
        }
    }

    // Horizontal stripe pattern (background detail)
    let sy = fract(hp.y * 8.0);
    if (sy < 0.12 || sy > 0.88) { return base * 0.15; }
    return base;
}
```

B3: SOUTH WALL — COLOR CALIBRATION + BARCODE

```wgsl
fn south_wall(hp: vec3f) -> vec3f {
    let u = (hp.x + 5.0) / 10.0; // 0..1 across wall
    let v = hp.y / 3.0;           // 0..1 floor to ceiling

    // Top half: color gradient bars
    if (v > 0.5) {
        let row = i32((v - 0.5) * 12.0); // 6 rows
        let t = u; // gradient position 0..1
        switch (row) {
            case 0: { return vec3f(t, 0.0, 0.0); }          // black→red
            case 1: { return vec3f(0.0, t, 0.0); }          // black→green
            case 2: { return vec3f(0.0, 0.0, t); }          // black→blue
            case 3: {                                         // HSV hue sweep
                let h = t * 6.0;
                let hi = i32(h); let f = fract(h);
                switch (hi % 6) {
                    case 0: { return vec3f(1,f,0); }
                    case 1: { return vec3f(1.0-f,1,0); }
                    case 2: { return vec3f(0,1,f); }
                    case 3: { return vec3f(0,1.0-f,1); }
                    case 4: { return vec3f(f,0,1); }
                    default: { return vec3f(1,0,1.0-f); }
                }
            }
            case 4: {                                         // grey ramp 16 steps
                let step = floor(t * 16.0) / 15.0;
                return vec3f(step);
            }
            default: {                                        // skin tone gradient
                return mix(vec3f(0.95,0.80,0.65), vec3f(0.30,0.18,0.10), t);
            }
        }
    }

    // Bottom half: barcode pattern
    // Alternating bars of varying widths
    let bar_x = hp.x * 40.0; // 40 bars per 10m wall
    let bar_id = i32(floor(bar_x + 200.0));
    // Pseudo-random bar widths from a hash
    let hash = u32(bar_id * 2654435761); // Knuth multiplicative hash
    let is_black = (hash & 1u) == 0u;
    let bar_width_mod = f32((hash >> 1u) & 3u); // 0-3
    let in_bar = fract(bar_x + 200.0) < (0.3 + bar_width_mod * 0.15);

    if (v > 0.15 && v < 0.45) {
        if (is_black && in_bar) { return vec3f(0.02); }
        return vec3f(0.95);
    }

    // QR-style finder pattern at bottom
    if (v < 0.12) {
        let qx = i32((hp.x + 1.0) * 10.0); // 21 cells across 2.1m
        let qy = i32(v * 21.0 * 3.0);
        if (qx >= 0 && qx < 21 && qy >= 0 && qy < 7) {
            // Finder pattern: concentric squares in corners
            let is_finder = (qx < 7 && qy < 7) || (qx >= 14 && qy < 7);
            if (is_finder) {
                let fx = select(qx, qx - 14, qx >= 14);
                let border = min(min(fx, 6-fx), min(qy, 6-qy));
                if (border == 0 || border == 2 || (fx >= 2 && fx <= 4 && qy >= 2 && qy <= 4)) {
                    return vec3f(0.02);
                }
                return vec3f(0.95);
            }
            // Data area: checkerboard with some pattern
            if ((qx + qy) % 2 == 0) { return vec3f(0.02); }
            return vec3f(0.95);
        }
    }

    return vec3f(0.0, 0.0, 0.7); // blue background
}
```

