```wgsl
fn east_wall(hp: vec3f) -> vec3f {
    let u = (hp.z + 5.0) / 10.0;
    let v = hp.y / 3.0;

    // Four quadrants: checkerboard at different scales
    let qx = select(0, 1, u > 0.5);
    let qy = select(0, 1, v > 0.5);
    let lu = fract(u * 2.0); // local u within quadrant
    let lv = fract(v * 2.0); // local v within quadrant

    let quad = qx + qy * 2;
    var scale = 1.0;
    switch (quad) {
        case 0: { scale = 2.0; }   // 50cm squares
        case 1: { scale = 10.0; }  // 10cm squares
        case 2: { scale = 25.0; }  // 4cm squares
        case 3: { scale = 50.0; }  // 2cm squares (near grid limit)
        default: {}
    }

    let cx = i32(floor(lu * scale));
    let cy = i32(floor(lv * scale));
    if ((cx + cy) % 2 == 0) { return vec3f(0.0, 0.85, 0.0); }
    return vec3f(0.02);
}
```

B5: WEST WALL — MATERIAL SWATCH GRID

```wgsl
fn west_wall(hp: vec3f) -> vec3f {
    let u = (hp.z + 5.0) / 10.0;
    let v = hp.y / 3.0;

    // 4x4 grid of material swatches
    let col = i32(u * 4.0);
    let row = i32(v * 4.0);
    if (col < 0 || col > 3 || row < 0 || row > 3) { return vec3f(0.8, 0.8, 0.0); }

    // Roughness increases left to right: 0.0, 0.3, 0.6, 1.0
    // Metallic increases bottom to top: 0.0, 0.33, 0.67, 1.0
    let rough = f32(col) / 3.0;
    let metal = f32(row) / 3.0;

    // Base color with visual roughness indication
    let base = mix(vec3f(0.8, 0.6, 0.1), vec3f(0.9, 0.9, 0.95), metal);

    // Add visual texture based on roughness
    let lu = fract(u * 4.0);
    let lv = fract(v * 4.0);
    // Border
    if (lu < 0.03 || lu > 0.97 || lv < 0.03 || lv > 0.97) { 
        return vec3f(0.1); 
    }
    // Roughness-based noise
    if (rough > 0.5) {
        let n = fract(sin(lu*127.1+lv*311.7)*43758.5);
        return mix(base, base * 0.7, n * rough * 0.3);
    }
    return base;
}
```

B6: FLOOR — PRECISION RULER + COMPASS

```wgsl
fn floor_pattern(hp: vec3f) -> vec3f {
    let tx = i32(floor(hp.x + 5.0));
    let tz = i32(floor(hp.z + 5.0));
    var col = select(vec3f(0.08), vec3f(0.92), (tx+tz)%2==0);

    // Compass arrows
    // North (red, -Z)
    if (abs(hp.x)<0.12 && hp.z<-0.5 && hp.z>-3.5) { col=vec3f(0.9,0,0); }
    if (hp.z<-3.0 && hp.z>-3.8 && abs(hp.x)<(-hp.z-3.0)*0.6) { col=vec3f(0.9,0,0); }
    // East (green, +X)
    if (abs(hp.z)<0.12 && hp.x>0.5 && hp.x<3.5) { col=vec3f(0,0.8,0); }
    if (hp.x>3.0 && hp.x<3.8 && abs(hp.z)<(hp.x-3.0)*0.6) { col=vec3f(0,0.8,0); }
    // South (blue, +Z)
    if (abs(hp.x)<0.08 && hp.z>0.5 && hp.z<2.5) { col=vec3f(0,0,0.9); }
    // West (yellow, -X)
    if (abs(hp.z)<0.08 && hp.x<-0.5 && hp.x>-2.5) { col=vec3f(0.9,0.9,0); }

    // Center cross
    if (abs(hp.x)<0.04 && abs(hp.z)<0.25) { col=vec3f(1.0); }
    if (abs(hp.z)<0.04 && abs(hp.x)<0.25) { col=vec3f(1.0); }

    // Distance rings
    let dist = sqrt(hp.x*hp.x + hp.z*hp.z);
    for (var r = 1; r <= 4; r++) {
        if (abs(dist-f32(r)) < 0.025) { col = vec3f(0.4,0.4,0.5); }
    }

    // Ruler ticks along X axis (at z=0 ± 0.1)
    if (abs(hp.z) < 0.1) {
        let ax = abs(hp.x);
        // Major ticks at 1m
        if (fract(ax) < 0.03 && ax > 0.5) { col = vec3f(1.0,0.2,0.2); }
        // Minor ticks at 10cm
        if (fract(ax * 10.0) < 0.04 && abs(hp.z) < 0.06) { col = vec3f(0.6); }
    }

    return col;
}
```

