fn ceiling_pattern(hp: vec3f) -> vec3f {
    let dist = sqrt(hp.x*hp.x + hp.z*hp.z);

    // Fresnel zone plate: ring spacing decreases as sqrt(n)
    let n = dist * dist * 4.0; // wavelength-scaled
    let zone = i32(floor(n));
    var col = select(vec3f(0.02), vec3f(0.8, 0.0, 0.8), zone % 2 == 0);

    // Crosshair
    if (abs(hp.x) < 0.03 || abs(hp.z) < 0.03) { col = vec3f(1.0, 0.9, 0.0); }

    // Center dot
    if (dist < 0.1) { col = vec3f(1.0); }

    return col;
}
