pub struct EntityRegistry {
    pub entities: Vec<Entity>,
}

impl EntityRegistry {
    pub fn new() -> Self { Self { entities: Vec::new() } }
    pub fn add(&mut self, e: Entity) -> usize { /* ... */ }
    pub fn gpu_buffer(&self) -> Vec<GpuEntity> { 
        self.entities.iter().map(|e| e.gpu).collect() 
    }
    pub fn update_physics(&mut self, dt: f32, elapsed: f32) {
        for e in &mut self.entities {
            // Rotation
            if e.angular_velocity.abs() > 0.001 {
                let angle = elapsed * e.angular_velocity;
                let half = angle * 0.5;
                e.gpu.rotation = [0.0, half.sin(), 0.0, half.cos()];
            }
            // Squish spring
            if e.squish.abs() > 0.001 || e.squish_velocity.abs() > 0.001 {
                let accel = -25.0 * (e.squish - 0.15) - 4.0 * e.squish_velocity;
                e.squish_velocity += accel * dt;
                e.squish += e.squish_velocity * dt;
                e.squish = e.squish.clamp(0.0, 0.9);
            }
        }
    }
}
