fn cell_count_3d() -> u32 { return params.grid_nx * params.grid_ny * params.grid_nz; }
fn cell_w(ci: u32) -> u32 { return ci / cell_count_3d(); }

fn cell_center(ci: u32) -> vec3f {
    let c3 = ci % cell_count_3d();
    let x = c3 % params.grid_nx;
    let y = (c3 / params.grid_nx) % params.grid_ny;
    let z = c3 / (params.grid_nx * params.grid_ny);
    let cs = params.cell_size;
    let half = vec3f(f32(params.grid_nx), 0.0, f32(params.grid_nz)) * cs * 0.5;
    return vec3f((f32(x) + 0.5) * cs - half.x, (f32(y) + 0.5) * cs, (f32(z) + 0.5) * cs - half.z);
}

fn room_sdf(p: vec3f) -> f32 {
    let half = vec3f(5.0, 1.5, 5.0);
    let center = vec3f(0.0, 1.5, 0.0);
    let d = abs(p - center) - half;
    return min(max(d.x, max(d.y, d.z)), 0.0) + length(max(d, vec3f(0.0)));
}

fn classify_room(p: vec3f) -> f32 {
    let half = vec3f(5.0, 1.5, 5.0);
    let center = vec3f(0.0, 1.5, 0.0);
    let d = abs(p - center) - half;
    if (d.x > d.y && d.x > d.z) { return select(5.0, 6.0, p.x > 0.0); } // east/west
    if (d.z > d.y) { return select(3.0, 4.0, p.z > 0.0); } // north/south
    return select(1.0, 2.0, p.y > center.y); // floor/ceiling
}

fn quat_rotate(p: vec3f, q: vec4f) -> vec3f {
    let u = q.xyz; let s = q.w;
    return 2.0*dot(u,p)*u + (s*s-dot(u,u))*p + 2.0*s*cross(u,p);
}

fn eval_entity(p: vec3f, e: GpuEntity) -> f32 {
    let center = vec3f(e.pos_x, e.pos_y, e.pos_z);
    let q = vec4f(e.rot_x, e.rot_y, e.rot_z, e.rot_w);
    let local = quat_rotate(p - center, vec4f(-q.xyz, q.w)) / e.scale;
    switch (e.kind) {
        case 0u: { return (length(local) - e.param0) * e.scale; }
        case 1u: { let q2=abs(local)-vec3f(e.param0,e.param1,e.param2);
                    return (length(max(q2,vec3f(0)))+min(max(q2.x,max(q2.y,q2.z)),0.0))*e.scale; }
        case 2u: { let dr=sqrt(local.x*local.x+local.z*local.z)-e.param0;
                    let dv=abs(local.y)-e.param1*0.5;
                    return (length(max(vec2f(dr,dv),vec2f(0)))+min(max(dr,dv),0.0))*e.scale; }
        case 3u: { let qxz=sqrt(local.x*local.x+local.z*local.z)-e.param0;
                    return (sqrt(qxz*qxz+local.y*local.y)-e.param1)*e.scale; }
        default: { return 999.0; }
    }
}

