fn main([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let ci = gid.x;
    let total = cell_count_3d() * params.grid_nw;
    if (ci >= total) { return; }

    let w = cell_w(ci);
    let p = cell_center(ci);

    // Room geometry (w=0 only)
    var sdf = 999.0;
    var st = 0.0;
    if (w == 0u) {
        sdf = -room_sdf(p); // negative inside room
        if (sdf < 0.0) { // inside walls
            st = classify_room(p);
        }
    }

    // Entity stamps
    for (var i = 0u; i < params.num_entities; i++) {
        let e = entities[i];
        if (u32(e.w_layer) != w) { continue; }
        let d = eval_entity(p, e);
        if (d < sdf) {
            sdf = d;
            st = e.surface_type;
            field[ci].mat_p0 = e.mat_idx;
        }
    }

    field[ci].phi = select(0.0, 1.0, sdf < 0.0);
    field[ci].pseudo_sdf = sdf;
    field[ci].surface_type = st;
}

