[redacted:social-handle] [redacted:social-handle](256)
fn compute_normals([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let ci = gid.x;
    let total = cell_count_3d() * params.grid_nw;
    if (ci >= total) { return; }

    let nx = params.grid_nx; let ny = params.grid_ny; let nz = params.grid_nz;
    let c3 = ci % cell_count_3d();
    let x = c3 % nx; let y = (c3/nx)%ny; let z = c3/(nx*ny);
    let w_off = (ci / cell_count_3d()) * cell_count_3d();

    let xm = select(field[w_off + (x-1u)+y*nx+z*nx*ny].phi, 0.0, x==0u);
    let xp = select(field[w_off + (x+1u)+y*nx+z*nx*ny].phi, 0.0, x>=nx-1u);
    let ym = select(field[w_off + x+(y-1u)*nx+z*nx*ny].phi, 0.0, y==0u);
    let yp = select(field[w_off + x+(y+1u)*nx+z*nx*ny].phi, 0.0, y>=ny-1u);
    let zm = select(field[w_off + x+y*nx+(z-1u)*nx*ny].phi, 0.0, z==0u);
    let zp = select(field[w_off + x+y*nx+(z+1u)*nx*ny].phi, 0.0, z>=nz-1u);

    // Negate gradient: -∇φ points outward from solid
    let n = vec3f(xm-xp, ym-yp, zm-zp);
    let len = length(n);
    let norm = select(vec3f(0,1,0), n/len, len > 0.0001);

    field[ci].normal_x = norm.x;
    field[ci].normal_y = norm.y;
    field[ci].normal_z = norm.z;
}
