pub const NX: u32 = 80;
pub const NY: u32 = 24;
pub const NZ: u32 = 80;
pub const NW: u32 = 4;
pub const CS: f32 = 0.125;
pub const ROOM_HALF: [f32; 3] = [4.65, 1.3, 4.65]; // wall shell = 0.35m

pub fn cell_count_3d() -> u32 { NX * NY * NZ }
pub fn cell_count() -> u32 { cell_count_3d() * NW }

pub fn idx(x: u32, y: u32, z: u32) -> u32 { 
    x + y * NX + z * NX * NY 
}
pub fn idx_4d(x: u32, y: u32, z: u32, w: u32) -> u32 { 
    idx(x, y, z) + w * cell_count_3d() 
}

pub fn cell_center(ci: u32) -> [f32; 3] {
    let c3 = ci % cell_count_3d();
    let x = c3 % NX;
    let y = (c3 / NX) % NY;
    let z = c3 / (NX * NY);
    [
        (x as f32 + 0.5) * CS - (NX as f32 * CS * 0.5),
        (y as f32 + 0.5) * CS,
        (z as f32 + 0.5) * CS - (NZ as f32 * CS * 0.5),
    ]
}

pub fn world_to_cell(p: [f32; 3]) -> Option<u32> {
    let x = ((p[0] + NX as f32 * CS * 0.5) / CS) as i32;
    let y = (p[1] / CS) as i32;
    let z = ((p[2] + NZ as f32 * CS * 0.5) / CS) as i32;
    if x < 0 || y < 0 || z < 0 || x >= NX as i32 || y >= NY as i32 || z >= NZ as i32 {
        return None;
    }
    Some(idx(x as u32, y as u32, z as u32))
}
