pub struct Camera {
    pub position: [f32; 3],
    pub yaw: f32,   // radians
    pub pitch: f32,  // radians
    pub fov: f32,    // radians
    pub forward: [f32; 3],
    pub up: [f32; 3],
}

impl Camera {
    pub fn new() -> Self {
        let mut cam = Self {
            position: [0.0, 1.0, 3.0],
            yaw: -std::f32::consts::FRAC_PI_2,
            pitch: 0.0,
            fov: 1.2,
            forward: [0.0, 0.0, -1.0],
            up: [0.0, 1.0, 0.0],
        };
        cam.update_direction();
        cam
    }

    pub fn update_direction(&mut self) {
        self.forward = [
            self.yaw.cos() * self.pitch.cos(),
            self.pitch.sin(),
            self.yaw.sin() * self.pitch.cos(),
        ];
        // up stays [0,1,0] — the shader computes the real up from cross products
        self.up = [0.0, 1.0, 0.0];
    }

    pub fn clamp_to_room(&mut self) {
        use super::grid::*;
        let margin = 0.3;
        self.position[0] = self.position[0].clamp(-ROOM_HALF[0] + margin, ROOM_HALF[0] - margin);
        self.position[1] = self.position[1].clamp(margin, ROOM_HALF[1] * 2.0 - margin);
        self.position[2] = self.position[2].clamp(-ROOM_HALF[2] + margin, ROOM_HALF[2] - margin);
    }
}
