pub struct DerivePass {
    geometry_pipeline: wgpu::ComputePipeline,
    normals_pipeline: wgpu::ComputePipeline,
    bind_group_layout: wgpu::BindGroupLayout,
}

impl DerivePass {
    pub fn new(device: &wgpu::Device) -> Self {
        let wgsl = include_str!("../../../shaders/derive_field.wgsl");
        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("derive_field"),
            source: wgpu::ShaderSource::Wgsl(wgsl.into()),
        });

        let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("derive_bgl"),
            entries: &[
                // [redacted:social-handle](0) observer_field: array<ObserverCell> (read_write)
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: false },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                // [redacted:social-handle](1) physics_field: array<PhysicsCell> (read_write)
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: false },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                // [redacted:social-handle](2) params: uniform
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
            ],
        });

        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("derive_layout"),
            bind_group_layouts: &[&bind_group_layout],
            push_constant_ranges: &[],
        });

        let geometry_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("derive_geometry"),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some("derive_geometry"),
            compilation_options: Default::default(),
            cache: None,
        });

        let normals_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("derive_normals"),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some("derive_normals"),
            compilation_options: Default::default(),
            cache: None,
        });

        Self { geometry_pipeline, normals_pipeline, bind_group_layout }
    }

    pub fn dispatch(&self, encoder: &mut wgpu::CommandEncoder, 
                    bind_group: &wgpu::BindGroup) {
        let workgroups = (loa_core::grid::cell_count() + 255) / 256;

        // Pass 1: compute SDF + surface_type
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&self.geometry_pipeline);
            pass.set_bind_group(0, bind_group, &[]);
            pass.dispatch_workgroups(workgroups, 1, 1);
        }
        // Pass 2: compute normals from phi gradient
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&self.normals_pipeline);
            pass.set_bind_group(0, bind_group, &[]);
            pass.dispatch_workgroups(workgroups, 1, 1);
        }
    }

    pub fn bind_group_layout(&self) -> &wgpu::BindGroupLayout { &self.bind_group_layout }
}
