fn cc3() -> u32 { return params.grid_nx * params.grid_ny * params.grid_nz; }

fn cell_center(ci: u32) -> vec3f {
    let c3 = ci % cc3();
    let x = c3 % params.grid_nx;
    let y = (c3 / params.grid_nx) % params.grid_ny;
    let z = c3 / (params.grid_nx * params.grid_ny);
    let cs = params.cell_size;
    let hx = f32(params.grid_nx) * cs * 0.5;
    let hz = f32(params.grid_nz) * cs * 0.5;
    return vec3f((f32(x)+0.5)*cs - hx, (f32(y)+0.5)*cs, (f32(z)+0.5)*cs - hz);
}

fn room_sdf(p: vec3f) -> f32 {
    // Room interior: negative inside, positive outside (in walls)
    let half = vec3f(4.65, 1.3, 4.65);
    let center = vec3f(0.0, 1.5, 0.0); // room center at y=1.5 (floor at 0, ceiling at 3)
    let d = abs(p - center) - half;
    // Positive outside the box (inside walls), negative inside the box (room interior)
    return length(max(d, vec3f(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

fn classify_surface(p: vec3f) -> f32 {
    let half = vec3f(4.65, 1.3, 4.65);
    let center = vec3f(0.0, 1.5, 0.0);
    let d = abs(p - center) - half;
    // Which face of the box is closest?
    if (d.y > d.x && d.y > d.z) {
        return select(1.0, 2.0, p.y > center.y); // floor=1, ceiling=2
    }
    if (d.x > d.z) {
        return select(6.0, 5.0, p.x > 0.0); // west=6, east=5
    }
    return select(3.0, 4.0, p.z > 0.0); // north=3 (-Z), south=4 (+Z)
}

[redacted:social-handle] [redacted:social-handle](256)
fn derive_geometry([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let ci = gid.x;
    if (ci >= cc3() * params.grid_nw) { return; }

    let w = ci / cc3();
    let p = cell_center(ci);

    var sdf = 5.0; // default: far outside (void)
    var st = 0.0;  // air

    if (w == 0u) {
        sdf = room_sdf(p);
        // sdf < 0 means inside room (air), sdf > 0 means inside walls (solid)
        // For the observer, we want pseudo_sdf positive in air, negative in solid
        // So we negate: the observer marches toward surfaces where pseudo_sdf crosses zero
        let obs_sdf = -sdf; // positive inside room, negative inside walls

        // Near surfaces, classify
        if (abs(sdf) < params.cell_size * 3.0) {
            st = classify_surface(p);
        }

        obs[ci].pseudo_sdf = obs_sdf;

        // phi: 1.0 = solid (wall), 0.0 = air (room interior)
        let phi = smoothstep(-params.cell_size, params.cell_size, sdf);
        phys[ci].phi = phi;
        phys[ci].sdf_raw = sdf;
    } else {
        obs[ci].pseudo_sdf = -5.0; // void in w>0 layers (no room)
        phys[ci].phi = 0.0;
        phys[ci].sdf_raw = 5.0;
    }

    obs[ci].surface_type = st;
    obs[ci].mat_p0 = 0.0;
}

[redacted:social-handle] [redacted:social-handle](256)
fn derive_normals([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let ci = gid.x;
    if (ci >= cc3() * params.grid_nw) { return; }

    let nx = params.grid_nx;
    let ny = params.grid_ny;
    let nz = params.grid_nz;
    let c3 = ci % cc3();
    let x = c3 % nx;
    let y = (c3 / nx) % ny;
    let z = c3 / (nx * ny);
    let w_off = (ci / cc3()) * cc3();

    // Read phi from neighbors (same w-layer only)
    let xm = select(phys[w_off + (x-1u) + y*nx + z*nx*ny].phi, phys[ci].phi, x == 0u);
    let xp = select(phys[w_off + (x+1u) + y*nx + z*nx*ny].phi, phys[ci].phi, x >= nx-1u);
    let ym = select(phys[w_off + x + (y-1u)*nx + z*nx*ny].phi, phys[ci].phi, y == 0u);
    let yp = select(phys[w_off + x + (y+1u)*nx + z*nx*ny].phi, phys[ci].phi, y >= ny-1u);
    let zm = select(phys[w_off + x + y*nx + (z-1u)*nx*ny].phi, phys[ci].phi, z == 0u);
    let zp = select(phys[w_off + x + y*nx + (z+1u)*nx*ny].phi, phys[ci].phi, z >= nz-1u);

    // -∇φ: points outward from solid (into room interior)
    let n = vec3f(xm - xp, ym - yp, zm - zp);
    let len = length(n);
    let norm = select(vec3f(0.0, 1.0, 0.0), n / len, len > 0.0001);

    obs[ci].normal_x = norm.x;
    obs[ci].normal_y = norm.y;
    obs[ci].normal_z = norm.z;
}
