    pseudo_sdf: f32,
    surface_type: f32,
    mat_p0: f32,
    normal_x: f32, normal_y: f32, normal_z: f32,
}

struct Camera {
    pos: vec3f, fov: f32,
    forward: vec3f, mode: u32,
    up: vec3f, cell_size: f32,
    grid_nx: u32, grid_ny: u32, grid_nz: u32, grid_nw: u32,
    screen_w: u32, screen_h: u32, elapsed: f32, camera_w: f32,
}

[redacted:social-handle](0) [redacted:social-handle](0) var<storage, read> field: array<ObserverCell>;
[redacted:social-handle](0) [redacted:social-handle](1) var<uniform> cam: Camera;
[redacted:social-handle](0) [redacted:social-handle](2) var output: texture_storage_2d<rgba8unorm, write>;

fn cc3() -> u32 { return cam.grid_nx * cam.grid_ny * cam.grid_nz; }

// Trilinear sample of pseudo_sdf from ObserverField
fn sample_sdf(p: vec3f, w: i32) -> f32 {
    let cs = cam.cell_size;
    let hx = f32(cam.grid_nx) * cs * 0.5;
    let hz = f32(cam.grid_nz) * cs * 0.5;
    let g = vec3f((p.x + hx) / cs - 0.5, p.y / cs - 0.5, (p.z + hz) / cs - 0.5);
    let nx = i32(cam.grid_nx); let ny = i32(cam.grid_ny); let nz = i32(cam.grid_nz);
    let x0 = clamp(i32(floor(g.x)), 0, nx-1); let y0 = clamp(i32(floor(g.y)), 0, ny-1);
    let z0 = clamp(i32(floor(g.z)), 0, nz-1);
    let x1 = min(x0+1, nx-1); let y1 = min(y0+1, ny-1); let z1 = min(z0+1, nz-1);
    let f = clamp(g - vec3f(f32(x0), f32(y0), f32(z0)), vec3f(0.0), vec3f(1.0));
    let wc = clamp(w, 0, i32(cam.grid_nw)-1);
    let wo = u32(wc) * cc3();
    let unx = cam.grid_nx;
    let i000 = wo+u32(x0)+u32(y0)*unx+u32(z0)*unx*cam.grid_ny;
    let i100 = wo+u32(x1)+u32(y0)*unx+u32(z0)*unx*cam.grid_ny;
    let i010 = wo+u32(x0)+u32(y1)*unx+u32(z0)*unx*cam.grid_ny;
    let i110 = wo+u32(x1)+u32(y1)*unx+u32(z0)*unx*cam.grid_ny;
    let i001 = wo+u32(x0)+u32(y0)*unx+u32(z1)*unx*cam.grid_ny;
    let i101 = wo+u32(x1)+u32(y0)*unx+u32(z1)*unx*cam.grid_ny;
    let i011 = wo+u32(x0)+u32(y1)*unx+u32(z1)*unx*cam.grid_ny;
    let i111 = wo+u32(x1)+u32(y1)*unx+u32(z1)*unx*cam.grid_ny;
    let c00 = mix(field[i000].pseudo_sdf, field[i100].pseudo_sdf, f.x);
    let c10 = mix(field[i010].pseudo_sdf, field[i110].pseudo_sdf, f.x);
    let c01 = mix(field[i001].pseudo_sdf, field[i101].pseudo_sdf, f.x);
    let c11 = mix(field[i011].pseudo_sdf, field[i111].pseudo_sdf, f.x);
    return mix(mix(c00, c10, f.y), mix(c01, c11, f.y), f.z);
}

fn sample_normal(p: vec3f, w: i32) -> vec3f {
    let cs = cam.cell_size;
    let hx = f32(cam.grid_nx) * cs * 0.5;
    let hz = f32(cam.grid_nz) * cs * 0.5;
    let g = vec3f((p.x+hx)/cs, p.y/cs, (p.z+hz)/cs);
    let x = clamp(i32(g.x), 0, i32(cam.grid_nx)-1);
    let y = clamp(i32(g.y), 0, i32(cam.grid_ny)-1);
    let z = clamp(i32(g.z), 0, i32(cam.grid_nz)-1);
    let ci = u32(clamp(w,0,i32(cam.grid_nw)-1))*cc3() + u32(x)+u32(y)*cam.grid_nx+u32(z)*cam.grid_nx*cam.grid_ny;
    return vec3f(field[ci].normal_x, field[ci].normal_y, field[ci].normal_z);
}

fn sample_surface_type(p: vec3f, w: i32) -> f32 {
    let cs = cam.cell_size;
    let hx = f32(cam.grid_nx) * cs * 0.5;
    let hz = f32(cam.grid_nz) * cs * 0.5;
    let g = vec3f((p.x+hx)/cs, p.y/cs, (p.z+hz)/cs);
    let x = clamp(i32(g.x), 0, i32(cam.grid_nx)-1);
    let y = clamp(i32(g.y), 0, i32(cam.grid_ny)-1);
    let z = clamp(i32(g.z), 0, i32(cam.grid_nz)-1);
    let ci = u32(clamp(w,0,i32(cam.grid_nw)-1))*cc3() + u32(x)+u32(y)*cam.grid_nx+u32(z)*cam.grid_nx*cam.grid_ny;
    return field[ci].surface_type;
}

// === Patterns ===
fn floor_pattern(p: vec3f) -> vec3f {
    let tx = i32(floor(p.x + 5.0));
    let tz = i32(floor(p.z + 5.0));
    var col = select(vec3f(0.08), vec3f(0.92), (tx+tz)%2==0);
    // Compass arrows
    if (abs(p.x)<0.12 && p.z<-0.5 && p.z>-3.5) { col = vec3f(0.9,0,0); }
    if (abs(p.z)<0.12 && p.x>0.5 && p.x<3.5) { col = vec3f(0,0.8,0); }
    // Distance rings
    let dist = sqrt(p.x*p.x+p.z*p.z);
    for (var r=1; r<=4; r++) { if (abs(dist-f32(r))<0.03) { col=vec3f(0.4); } }
    // Center cross
    if (abs(p.x)<0.04&&abs(p.z)<0.25) { col=vec3f(1); }
    if (abs(p.z)<0.04&&abs(p.x)<0.25) { col=vec3f(1); }
    return col;
}

fn ceiling_pattern(p: vec3f) -> vec3f {
    let dist = sqrt(p.x*p.x+p.z*p.z);
    let n = dist*dist*4.0;
    let zone = i32(floor(n));
    var col = select(vec3f(0.02), vec3f(0.8,0,0.8), zone%2==0);
    if (abs(p.x)<0.03||abs(p.z)<0.03) { col=vec3f(1,0.9,0); }
    if (dist<0.1) { col=vec3f(1); }
    return col;
}

fn wall_pattern(p: vec3f, wall_id: i32) -> vec3f {
    switch (wall_id) {
        case 3: { // north: red + horizontal stripes
            let sy = fract(p.y * 8.0);
            if (sy<0.12||sy>0.88) { return vec3f(0.15,0,0); }
            return vec3f(0.9,0,0);
        }
        case 4: { // south: blue + vertical stripes
            let sx = fract((p.x+5.0)*3.0);
            if (sx<0.1||sx>0.9) { return vec3f(0,0,0.12); }
            return vec3f(0,0,0.9);
        }
        case 5: { // east: green + checkerboard
            let tx=i32(floor(p.y*6.0)); let tz=i32(floor((p.z+5.0)*6.0));
            if ((tx+tz)%2==0) { return vec3f(0,0.9,0); }
            return vec3f(0.02);
        }
        case 6: { // west: yellow + grid
            let gy=fract(p.y*5.0); let gz=fract((p.z+5.0)*5.0);
            if (gy<0.06||gy>0.94||gz<0.06||gz>0.94) { return vec3f(0.12,0.1,0); }
            return vec3f(1,1,0);
        }
        default: { return vec3f(0.5); }
    }
}

fn shade(hp: vec3f, nor: vec3f, rd: vec3f, w: i32, mode: u32) -> vec3f {
    let st = sample_surface_type(hp, w);
    var albedo = vec3f(0.3);
    let sid = i32(st + 0.5);
    if (sid == 1) { albedo = floor_pattern(hp); }
    else if (sid == 2) { albedo = ceiling_pattern(hp); }
    else if (sid >= 3 && sid <= 6) { albedo = wall_pattern(hp, sid); }

    switch (mode) {
        case 1u: { return albedo; }
        case 3u: { return nor * 0.5 + 0.5; }
        default: {
            let l = normalize(vec3f(0.3, 1.0, 0.2));
            let ndl = max(dot(nor, l), 0.0);
            return albedo * (ndl * 0.8 + 0.05) * vec3f(0.7, 0.65, 0.6);
        }
    }
}

fn aces(x: vec3f) -> vec3f {
    let a = x * (x * 2.51 + 0.03);
    let b = x * (x * 2.43 + 0.59) + 0.14;
    return clamp(a / b, vec3f(0.0), vec3f(1.0));
}

[redacted:social-handle] [redacted:social-handle](8, 8, 1)
fn main_observe([redacted:social-handle](global_invocation_id) gid: vec3u) {
    let px = gid.x; let py = gid.y;
    if (px >= cam.screen_w || py >= cam.screen_h) { return; }

    let aspect = f32(cam.screen_w) / f32(cam.screen_h);
    let hh = tan(cam.fov * 0.5); let hw = hh * aspect;
    let fwd = normalize(cam.forward);
    let right = normalize(cross(fwd, cam.up));
    let cup = cross(right, fwd);
    let ndc_x = (f32(px)+0.5)/f32(cam.screen_w)*2.0-1.0;
    let ndc_y = 1.0-(f32(py)+0.5)/f32(cam.screen_h)*2.0;
    let rd = normalize(fwd + right*ndc_x*hw + cup*ndc_y*hh);
    let ro = cam.pos;
    let cs = cam.cell_size;
    let w = i32(cam.camera_w + 0.5);

    var color = vec3f(0.005, 0.005, 0.008);
    var t = cs * 3.0; // skip near-camera zone (anti-flicker)
    var prev_d = 100.0;

    for (var i = 0; i < 128; i++) {
        if (t > 30.0) { break; }
        let p = ro + rd * t;
        let d = sample_sdf(p, w);

        // Overshoot: bisect
        if (d < 0.0 && prev_d > 0.0) {
            var lo = t - max(prev_d, cs * 0.1);
            var hi = t;
            for (var b = 0; b < 6; b++) {
                let mid = (lo + hi) * 0.5;
                if (sample_sdf(ro + rd * mid, w) < 0.0) { hi = mid; } else { lo = mid; }
            }
            let hp = ro + rd * (lo + hi) * 0.5;
            let nor = sample_normal(hp, w);
            color = shade(hp, nor, rd, w, cam.mode);
            break;
        }

        // Near-surface hit
        if (d >= 0.0 && d < cs * 0.01) {
            let nor = sample_normal(p, w);
            color = shade(p, nor, rd, w, cam.mode);
            break;
        }

        prev_d = d;
        t += max(d * 0.9, cs * 0.05);
    }

    var out_col = select(clamp(color, vec3f(0), vec3f(1)), aces(color), cam.mode == 0u);
    textureStore(output, vec2i(i32(px), i32(py)), vec4f(out_col, 1.0));
}
